package scan

import (
	"fmt"
	"strings"
	"time"

	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/util"
)

const eolDateFormat = "2006-01-02"

// eolRelease converts detected patch releases to the identifiers in the
// lifecycle table. GetEOL itself remains an exact family/release lookup.
func eolRelease(family, release string) string {
	switch family {
	case config.RedHat, config.CentOS, config.Oracle, config.Debian:
		return util.Major(release)
	case config.FreeBSD:
		return util.Major(strings.SplitN(release, "-", 2)[0])
	case config.Ubuntu, config.Alpine:
		parts := strings.Split(release, ".")
		if len(parts) >= 2 {
			return strings.Join(parts[:2], ".")
		}
	}
	return release
}

// eolWarnings evaluates one target at the scan's supplied time, in display order.
func eolWarnings(family, release string, now time.Time) []string {
	if family == config.ServerTypePseudo || family == config.Raspbian {
		return nil
	}

	info, found := config.GetEOL(family, eolRelease(family, release))
	if !found {
		return []string{fmt.Sprintf("Failed to check EOL. Register the issue to https://github.com/future-architect/vuls/issues with the information in 'Family: %s Release: %s'", family, release)}
	}

	if info.IsStandardSupportEnded(now) {
		warnings := []string{"Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended."}
		if !info.ExtendedSupportUntil.IsZero() {
			if info.IsExtendedSuppportEnded(now) {
				warnings = append(warnings, "Extended support is also EOL. There are many Vulnerabilities that are not detected, Upgrading your OS strongly recommended.")
			} else {
				warnings = append(warnings, fmt.Sprintf("Extended support available until %s. Check the vendor site.", info.ExtendedSupportUntil.Format(eolDateFormat)))
			}
		}
		return warnings
	}

	if !now.AddDate(0, 3, 0).Before(info.StandardSupportUntil) {
		return []string{fmt.Sprintf("Standard OS support will be end in 3 months. EOL date: %s", info.StandardSupportUntil.Format(eolDateFormat))}
	}
	return nil
}
package config

import (
	"strings"
	"time"
)

// OS family identifiers used throughout scanning and lifecycle lookup.
const (
	RedHat                = "redhat"
	Debian                = "debian"
	Ubuntu                = "ubuntu"
	CentOS                = "centos"
	Fedora                = "fedora"
	Amazon                = "amazon"
	Oracle                = "oracle"
	FreeBSD               = "freebsd"
	Raspbian              = "raspbian"
	Windows               = "windows"
	OpenSUSE              = "opensuse"
	OpenSUSELeap          = "opensuse.leap"
	SUSEEnterpriseServer  = "suse.linux.enterprise.server"
	SUSEEnterpriseDesktop = "suse.linux.enterprise.desktop"
	SUSEOpenstackCloud    = "suse.openstack.cloud"
	Alpine                = "alpine"
	ServerTypePseudo      = "pseudo"
)

// Major removes an optional epoch and returns the part before the first dot.
// Kept here so config.Distro can share the parser without importing util.
func Major(version string) string {
	if i := strings.IndexByte(version, ':'); i >= 0 {
		version = version[i+1:]
	}
	if i := strings.IndexByte(version, '.'); i >= 0 {
		version = version[:i]
	}
	return version
}

// EOL describes the end of standard and optional extended OS support.
type EOL struct {
	StandardSupportUntil time.Time
	ExtendedSupportUntil time.Time
	Ended                bool
}

// IsStandardSupportEnded reports whether standard support is past its end date.
func (e EOL) IsStandardSupportEnded(now time.Time) bool {
	return !e.StandardSupportUntil.IsZero() && now.After(e.StandardSupportUntil)
}

// IsExtendedSuppportEnded reports whether applicable extended support has ended.
func (e EOL) IsExtendedSuppportEnded(now time.Time) bool {
	return !e.ExtendedSupportUntil.IsZero() && now.After(e.ExtendedSupportUntil)
}

// IsExtendedSupportEnded is the correctly spelled alias.
func (e EOL) IsExtendedSupportEnded(now time.Time) bool {
	return e.IsExtendedSuppportEnded(now)
}

func eol(standard, extended string) EOL {
	parse := func(value string) time.Time {
		if value == "" {
			return time.Time{}
		}
		date, err := time.Parse("2006-01-02", value)
		if err != nil {
			panic(err)
		}
		return date
	}
	return EOL{StandardSupportUntil: parse(standard), ExtendedSupportUntil: parse(extended)}
}

